#include <Cellerator/compiler/ir/realization/implement_graph_capture_and_rebind_contracts_v1.hh>
#include <set>
#include <tuple>
namespace cellerator::compiler::ir::realization::v1 {namespace{graph_capture_status_v1 fail(graph_capture_status_v1 s,std::string*e,const char*m)noexcept{if(e)*e=m;return s;}}
graph_capture_status_v1 validate_graph_capture_contract_v1(const graph_capture_contract_v1&c,std::string*e)noexcept{if(!c.capture_compatible)return fail(graph_capture_status_v1::not_capture_compatible,e,"capture compatibility required");if(!valid(c.identity))return fail(graph_capture_status_v1::invalid_identity,e,"capture identity required");std::set<std::tuple<std::uint64_t,std::uint64_t>>ids;for(const auto&b:c.graph_stable_bindings)if(!valid(b.symbolic_binding)||!valid(b.address_identity)||!ids.emplace(b.symbolic_binding.high,b.symbolic_binding.low).second)return fail(graph_capture_status_v1::duplicate_binding,e,"unique symbolic and address identities required");if(e)e->clear();return graph_capture_status_v1::valid;}
graph_capture_status_v1 validate_graph_rebind_v1(const graph_capture_contract_v1&c,const graph_rebind_request_v1&r,std::string*e)noexcept{auto s=validate_graph_capture_contract_v1(c,e);if(s!=graph_capture_status_v1::valid)return s;if((r.changed_fields&~c.rebindable_fields)!=0)return fail(graph_capture_status_v1::field_not_rebindable,e,"changed field is fixed");if(r.address_identities.size()!=c.graph_stable_bindings.size())return fail(graph_capture_status_v1::address_count_mismatch,e,"address identity count mismatch");for(std::size_t i=0;i<r.address_identities.size();++i)if(c.graph_stable_bindings[i].fixed&&!(r.address_identities[i]==c.graph_stable_bindings[i].address_identity))return fail(graph_capture_status_v1::fixed_binding_changed,e,"graph-stable fixed address changed");if(c.replay==replay_variant_v1::recapture&&r.changed_fields)return fail(graph_capture_status_v1::recapture_required,e,"requested update requires recapture");if(e)e->clear();return graph_capture_status_v1::valid;}
} // namespace cellerator::compiler::ir::realization::v1
